compile.workshop:
variables {
    global:
        0: value
        8: I
}

rule ("issue 47 control flow") {
    event {
        Ongoing - Global;
    }
    actions {
        Modify Global Variable(value, Add, 1);
        Skip If(Compare(Global.value, ==, 1), 2);
        Modify Global Variable(value, Add, 10);
        Loop If(Compare(Global.value, <, 2));
        //__label_break_2__:
        If(Compare(Global.value, ==, 2));
            Set Global Variable(value, 3);
        Else If(Compare(Global.value, ==, 4));
            Set Global Variable(value, 5);
        Else;
            Set Global Variable(value, 6);
        End;
        For Global Variable(I, 0, 2, 1);
            If(Compare(Global.I, ==, 1));
                Modify Global Variable(value, Add, 1);
            End;
        End;
        While(Compare(Global.value, <, 5));
            Modify Global Variable(value, Add, 1);
        End;
        If(True);
            Skip(Value In Array(Array(3, 0, 1), Add(1, Index Of Array Value(Array(5, 6), Global.value))));
        //__label_switch_3_0__:
        Set Global Variable(value, 6);
        //__label_switch_3_1__:
        Set Global Variable(value, 7);
        Else;
        //__label_switch_3_default__:
        Set Global Variable(value, 8);
        End;
    }
}

